struct Surface {HDC dc;HBITMAP bitmap;HGDIOBJ old;void*bits;Surface(){dc=CreateCompatibleDC(NULL);BITMAPINFO bi={};bi.bmiHeader.biSize=40;bi.bmiHeader.biWidth=W;bi.bmiHeader.biHeight=-H;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;bi.bmiHeader.biCompression=BI_RGB;bitmap=CreateDIBSection(dc,&bi,DIB_RGB_COLORS,&bits,NULL,0);if(!bitmap||!dc)throw std::runtime_error("DIB");old=SelectObject(dc,bitmap);PatBlt(dc,0,0,W,H,WHITENESS);}~Surface(){SelectObject(dc,old);DeleteObject(bitmap);DeleteDC(dc);}};
static std::vector<unsigned char> bytes(const fs::path&p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("input");auto n=f.tellg();if(n<0||n>16777216)throw std::runtime_error("size");std::vector<unsigned char>b((size_t)n);f.seekg(0);f.read((char*)b.data(),b.size());return b;}
static unsigned short u16(const std::vector<unsigned char>&b,size_t i){return b[i]|(b[i+1]<<8);}static unsigned long u32(const std::vector<unsigned char>&b,size_t i){return u16(b,i)|((unsigned long)u16(b,i+2)<<16);}
static void pixels(Bitmap&b,const fs::path&dir,const std::string&name,std::ostream&o){Status status=b.Save((dir/(name+".png")).c_str(),&png,NULL);std::ofstream raw(dir/(name+".rgba"),std::ios::binary);int x0=W,y0=H,x1=-1,y1=-1,count=0;for(int y=0;y<H;y++)for(int x=0;x<W;x++){Color c;b.GetPixel(x,y,&c);unsigned char v[]={c.GetR(),c.GetG(),c.GetB(),255};raw.write((char*)v,4);if(v[0]!=255||v[1]!=255||v[2]!=255){x0=std::min(x0,x);y0=std::min(y0,y);x1=std::max(x1,x);y1=std::max(y1,y);count++;}}o<<"{\"png\":\""<<name<<".png\",\"saveStatus\":"<<status<<",\"nonwhitePixels\":"<<count<<",\"paintedBounds\":["<<x0<<","<<y0<<","<<x1<<","<<y1<<"]}";}
